<?php
namespace App\Http\Controllers; use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\Support\Facades\Hash;
class ProfileController extends Controller { public function edit(){return view('profile.edit');} public function update(Request $r){$u=$r->user();$d=$r->validate(['name'=>'required|string|max:100','email'=>['required','email',Rule::unique('users')->ignore($u)],'phone'=>['required','max:20',Rule::unique('users')->ignore($u)]]);$u->update($d);return back()->with('success','Profile updated successfully.');} public function password(Request $r){$d=$r->validate(['current_password'=>'required|current_password','password'=>'required|min:8|confirmed']);$r->user()->update(['password'=>$d['password']]);return back()->with('success','Password updated successfully.');}}
